from pathlib import Path
import os,json,subprocess,hashlib,base64,fcntl,tarfile
base=Path('/home/ubuntu/spacepdhcg-collect-tables-v290');repo=base/'repo'
for v in [291,292,293,294]:
 r=json.loads(Path('/home/ubuntu/spacepdhcg-collect-tables-campaign-v'+str(v)+'/report.json').read_text());assert r['complete'] and r['returncode']==0
root=Path('/home/ubuntu/spacepdhcg-collect-tables-final-v295');root.mkdir(exist_ok=False)
test=root/'test_gtoc12_gpu_collect_tables.py';test.write_bytes(base64.b64decode(''))
core=Path('/home/ubuntu/spacepdhcg-collect-dp-v279/core-build/cuda/libspacepdhcg_cuda.so')
env=os.environ.copy();env.update(PYTHONPATH=str(repo/'src'),SPACEPDHCG_GTOC12_CUDA_LIBRARY=str(core),SPACEPDHCG_GTOC12_DATA='/home/ubuntu/spacepdhcg/gtoc12/benchmarks/gtoc12/data',SPACEPDHCG_GTOC12_GPU_TESTS='1',OPENBLAS_NUM_THREADS='1',OMP_NUM_THREADS='1')
cmd=['/home/ubuntu/spacepdhcg/v1/.venv/bin/python','-c',"import sys,runpy;sys.meta_path=[f for f in sys.meta_path if f.__class__.__module__!='_editable_skbc_spacepdhcg'];runpy.run_module('pytest',run_name='__main__')",str(test),'-q']
with open('/home/ubuntu/.spacepdhcg-gpu.lock','a') as lock:
 fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
 with (root/'tests.log').open('w') as log:r=subprocess.run(cmd,cwd=repo,env=env,stdout=log,stderr=subprocess.STDOUT,timeout=30)
report=dict(returncode=r.returncode,command=cmd,test_sha256=hashlib.sha256(test.read_bytes()).hexdigest(),runtime_sha256=hashlib.sha256(core.read_bytes()).hexdigest())
(root/'report.json').write_text(json.dumps(report,indent=2));r.check_returncode()
archive=Path('/tmp/collect-tables-v295.tar.gz')
with tarfile.open(archive,'w:gz') as tar:
 for name in ['report.json','run.py','tests.log','memcheck.log','replay.log','replay.json','benchmark.log','benchmark.json']:
  tar.add(base/name,arcname='h100/'+name)
 for name in json.loads((base/'report.json').read_text())['source_sha256']:
  tar.add(repo/name,arcname='source/'+name)
 for name in ['test_gtoc12_gpu_collect_tables.py','report.json','tests.log']:
  tar.add(root/name,arcname='h100-final-tests/'+name)
 for v in [291,292,293,294]:
  folder=Path('/home/ubuntu/spacepdhcg-collect-tables-campaign-v'+str(v))
  for name in ['report.json','run.py','campaign.log','output']:tar.add(folder/name,arcname='v'+str(v)+'/'+name)
 for name in ['report.json','run.py']:tar.add(Path('/home/ubuntu/spacepdhcg-tables-comparison-v292')/name,arcname='comparison/'+name)
print(json.dumps(dict(archive=str(archive),sha256=hashlib.sha256(archive.read_bytes()).hexdigest(),validation=report)))
